import type { Metadata } from "next";
import { SITE_NAME, SITE_TAGLINE } from "./site";

/**
 * Branded 1200x630 social card generated by `src/app/opengraph-image.tsx`.
 * Referenced explicitly so every page carries an `og:image` (file-based
 * metadata only applies to the segment it lives in).
 */
const SOCIAL_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${SITE_NAME} — ${SITE_TAGLINE}`,
};

interface PageMetadataInput {
  /** Page title WITHOUT the brand suffix — the root template appends it. */
  title: string;
  /** 140-160 characters, written for search intent. */
  description: string;
  /** Path on this site, e.g. "/services" (resolved against metadataBase). */
  path: string;
  type?: "website" | "article";
  /** `false` keeps the page out of the index (drafts, confirmation pages). */
  index?: boolean;
}

/**
 * Standard page metadata: unique title + description, a self-referencing
 * canonical and matching Open Graph / Twitter values.
 */
export function createPageMetadata({
  title,
  description,
  path,
  type = "website",
  index = true,
}: PageMetadataInput): Metadata {
  const socialTitle = `${title} | ${SITE_NAME}`;

  return {
    title,
    description,
    alternates: { canonical: path },
    ...(index ? {} : { robots: { index: false, follow: true } }),
    openGraph: {
      type,
      title: socialTitle,
      description,
      url: path,
      images: [SOCIAL_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title: socialTitle,
      description,
      images: [SOCIAL_IMAGE.url],
    },
  };
}
